package com.sho1kat.dto.userServiceDto.request;

import jakarta.validation.constraints.*;

/**
 * SUPER_ADMIN-only: credentials for a new administrator account. The password is
 * generated by user-service and delivered by mail — it is never supplied here.
 */
public record CreateAdminRequest(

        @NotBlank(message = "First name is required")
        @Size(max = 50, message = "First name must be at most 50 characters")
        String firstName,

        @Size(max = 50, message = "Middle name must be at most 50 characters")
        String middleName,

        @NotBlank(message = "Last name is required")
        @Size(max = 50, message = "Last name must be at most 50 characters")
        String lastName,

        @NotBlank(message = "Email is required")
        @Email(message = "Email is not valid")
        @Size(max = 150, message = "Email must be at most 150 characters")
        String email,

        @Pattern(regexp = "^\\+?[0-9]{7,15}$", message = "Phone number is not valid")
        String phoneNumber
) {
}
